package com.ptms.service; import com.ptms.domain.*; import com.ptms.dto.*; import com.ptms.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional public class VisitorService{private final VisitorRepository r;public VisitorService(VisitorRepository r){this.r=r;}public List<VisitorDto>all(){return r.findAll().stream().map(this::dto).toList();}public VisitorDto save(VisitorDto d){Visitor v=d.id()==null?new Visitor():r.findById(d.id()).orElseThrow();if(v.getVisitorCode()==null){v.setVisitorCode("TMP-"+System.nanoTime());r.saveAndFlush(v);v.setVisitorCode("V%04d".formatted(v.getId()));}v.setName(d.name());v.setNic(d.nic());v.setVehicleNumber(d.vehicleNumber());v.setHostDepartment(d.hostDepartment());return dto(r.save(v));}private VisitorDto dto(Visitor v){return new VisitorDto(v.getId(),v.getVisitorCode(),v.getName(),v.getNic(),v.getVehicleNumber(),v.getHostDepartment());}}
